from core import *
import json

def render(c):
    t,n=c.t,c.n
    intro={46:('One click. A little momentum.','Count repetitions, good ideas, or small wins. Start fresh whenever you like.'),47:('A lighter list for today.','Give the next few things a home. Add a task, mark it complete, and make room to focus.'),48:('Good questions, clear answers.','Open any question below. The details stay close at hand while you explore.'),49:('The details, at your pace.','Move between the overview, practical information, and the plan for the day.'),50:('A small quiz for a curious mind.','Three questions, one quiet challenge. Choose an answer for each, then see how you did.'),51:('Find your next useful thing.','Open the collection menu to explore well-made equipment and practical advice.'),52:('A place to pause and look.','A small photographic story, one frame at a time. Explore with the previous and next controls.'),53:('Settle into a good read.','Switch between light and dark reading modes. Keep the words; change the atmosphere.'),54:('Share the table fairly.','Work out a tip and divide the total without reaching for a second calculator.'),55:('Something good is on its way.','A new independent collection is getting its finishing touches. Here is the time remaining.'),56:('Make time to learn by doing.','Explore a small-group workshop and open the details before deciding what comes next.'),57:('A little light changes the room.','Try the switch and compare a quiet evening setting with a brighter working light.'),58:('Wait for green. Then go.','A simple test of attention: start a round, wait for the green signal, and react as quickly as you can.'),59:('A classic, with one more round.','Choose rock, paper, or scissors. Every round shows both choices and updates the match score.'),60:('Look closely. Remember a little.','Turn over two cards at a time and match the garden symbols. Clear all four pairs to finish.'),61:('A number is waiting to be found.','Use each hint to narrow your search. You have seven attempts to find the hidden number.')}
    c.heading,c.intro=intro[t]
    body=''
    if t==46:
        goal=12+n
        body=c.section('Your small-win counter',f'<div class="panel p-8 text-center interactive-stage"><p class="eyebrow accent">Today’s intention · {goal} clicks</p><output id="score" aria-live="polite" class="block text-6xl font-bold my-6">0</output><div class="flex flex-wrap justify-center gap-3">{btn("Count a win",attrs="id=increment")}{btn("Start over",attrs="id=reset",secondary=True)}</div><p id="counter-note" class="muted mt-5">Begin with one click.</p><progress id="counter-progress" class="mt-5 w-full max-w-sm" max="{goal}" value="0" aria-label="Progress toward your intention"></progress></div>')
        c.scripts.append(f'''let count=0;const score=document.getElementById('score'),note=document.getElementById('counter-note'),progress=document.getElementById('counter-progress');
function render(){{score.textContent=count;progress.value=Math.min(count,{goal});note.textContent=count>={goal}?'Intention reached. Keep going if you like.':({goal}-count)+' clicks to your intention.';}}
document.getElementById('increment').onclick=()=>{{count++;render();}};document.getElementById('reset').onclick=()=>{{count=0;render();}};''')
    elif t==47:
        todos=pick(['Water the balcony plants','Read one chapter','Plan the weekend walk','Reply to the studio brief','Prepare tomorrow’s lunch','Back up the travel photos','Book a library visit','Sketch three new ideas'],n,3)
        body=c.section('Make a little room',f'<div class="panel p-6 max-w-3xl mx-auto"><form id="todo-form" class="flex flex-col sm:flex-row gap-3"><div class="flex-1"><label for="new-task" class="text-sm font-semibold">Add a task</label><input id="new-task" class="field w-full rounded-lg p-3 mt-2" maxlength="100" required autocomplete="off"></div><button class="btn self-end" type="submit">Add task</button></form><p id="task-count" class="muted text-sm my-5" role="status"></p><ul id="task-list" class="space-y-3"></ul><p id="empty-tasks" class="muted py-5" hidden>A clear page. Add one thing you would like to do.</p></div>')
        c.scripts.append('''const list=document.getElementById('task-list'),input=document.getElementById('new-task');let taskId=0;
function update(){const boxes=[...list.querySelectorAll('input')];document.getElementById('task-count').textContent=boxes.filter(x=>x.checked).length+' of '+boxes.length+' completed';document.getElementById('empty-tasks').hidden=boxes.length>0;}
function addTask(text){const li=document.createElement('li'),label=document.createElement('label'),check=document.createElement('input'),span=document.createElement('span'),remove=document.createElement('button');li.className='flex items-center gap-3 p-3 rounded-lg border divider';label.className='flex items-center gap-3 flex-1 min-w-0';check.type='checkbox';check.id='task-'+(++taskId);span.textContent=text;span.className='break-words';label.append(check,span);remove.type='button';remove.textContent='Remove';remove.className='text-sm accent font-semibold';remove.setAttribute('aria-label','Remove '+text);check.onchange=()=>{span.style.textDecoration=check.checked?'line-through':'';update();};remove.onclick=()=>{li.remove();update();};li.append(label,remove);list.append(li);update();}
document.getElementById('todo-form').onsubmit=event=>{event.preventDefault();const text=input.value.trim();if(!text){input.setCustomValidity('Enter a task, not only spaces.');input.reportValidity();return;}addTask(text);input.value='';input.focus();};input.oninput=()=>input.setCustomValidity('');
'''+f'{json.dumps(todos)}.forEach(addTask);')
    elif t==48:
        body=c.faq('The questions we hear most')
        body=c.section('Read the whole guide',btn('Open all answers',attrs='id=expand-faq')+'<p class="muted text-sm mt-3">You can also open and close each question separately.</p>')+body
        c.scripts.append('''const toggle=document.getElementById('expand-faq');toggle.onclick=()=>{const all=[...document.querySelectorAll('details')],open=all.some(d=>!d.open);all.forEach(d=>d.open=open);toggle.textContent=open?'Close all answers':'Open all answers';};''')
    elif t==49:
        sets=[('A weekend in the hills',[('Overview','A gentle two-day route through forest paths and small villages. Start after breakfast and leave time for a long lunch.'),('What to bring','Comfortable walking shoes, a refillable bottle, a light waterproof layer, and a small notebook for the places you want to revisit.'),('The plan','Saturday: a riverside walk and a picnic at the mill. Sunday: a morning ridge route, followed by a late lunch in the village.')]),('The neighborhood workshop',[('Overview','A practical introduction to making useful things with simple tools, taught in a small, welcoming studio.'),('Materials','We provide responsibly sourced wood, shared hand tools, and protective equipment. Bring closed-toe shoes and a willingness to try.'),('Schedule','Begin with a tool demonstration at 10 AM. Practice joinery before lunch, then assemble and finish your own small shelf by 4 PM.')]),('A season of growing',[('Overview','A six-week community growing program, from preparing a small plot to sharing the first harvest.'),('Growing notes','Choose a sunny spot, improve the soil with compost, and water near the roots. The first session covers plant spacing and seed depth.'),('Meetings','We meet on Saturdays at 9 AM. Each session includes a short demonstration, time in the garden, and a shared cup of tea.')])]
        title,panels=sets[n%len(sets)]
        tabs='<div role="tablist" aria-label="Guide sections" class="flex flex-wrap gap-2 mb-6">'
        for i,(h,text) in enumerate(panels):tabs+=f'<button id="tab-{i}" type="button" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="panel-{i}" tabindex="{0 if i==0 else -1}" class="tab-button btn btn-secondary">{e(h)}</button>'
        tabs+='</div>'
        for i,(h,text) in enumerate(panels):tabs+=f'<div id="panel-{i}" role="tabpanel" aria-labelledby="tab-{i}" tabindex="0" {"hidden" if i else ""}><h3 class="text-xl font-bold mb-3">{e(h)}</h3>{p(text)}</div>'
        body=c.section(title,'<div class="panel p-6 md:p-8 interactive-stage">'+tabs+'</div>')
        c.scripts.append('''const tabs=[...document.querySelectorAll('[role=tab]')];function selectTab(index){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;document.getElementById(tab.getAttribute('aria-controls')).hidden=i!==index;});}
tabs.forEach((tab,i)=>{tab.onclick=()=>selectTab(i);tab.onkeydown=event=>{let next=i;if(event.key==='ArrowRight')next=(i+1)%tabs.length;else if(event.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selectTab(next);tabs[next].focus();};});''')
    elif t==50:
        title,qs=QUIZZES[(n-1)%len(QUIZZES)]
        form='<form id="quiz-form" class="panel p-6 md:p-8 space-y-7">'
        for i,(question,answers,correct) in enumerate(qs):
            form+=f'<fieldset><legend class="font-bold mb-3">{i+1}. {e(question)}</legend><div class="space-y-3">'
            for j,answer in enumerate(answers):form+=f'<label class="flex items-start gap-3 p-3 border divider rounded-lg"><input class="mt-1" type="radio" required name="question-{i}" value="{j}"><span>{e(answer)}</span></label>'
            form+='</div></fieldset>'
        form+='<div class="flex flex-wrap gap-3"><button class="btn" type="submit">Check my answers</button><button class="btn btn-secondary" type="reset">Try again</button></div><div id="quiz-result" class="panel p-5" role="status" hidden></div></form>'
        body=c.section(title,form)
        c.scripts.append('''const form=document.getElementById('quiz-form'),result=document.getElementById('quiz-result');const questions='''+json.dumps(qs)+''';form.onsubmit=event=>{event.preventDefault();let score=0;const data=new FormData(form),lines=[];questions.forEach((q,i)=>{const correct=Number(data.get('question-'+i))===q[2];if(correct)score++;lines.push((i+1)+'. '+(correct?'Correct':'Review')+' — '+q[1][q[2]]);});result.hidden=false;result.textContent=score+' / '+questions.length+' correct. '+lines.join(' · ');};form.onreset=()=>{result.hidden=true;result.textContent='';};''')
    elif t==51:
        menu=f'<div class="relative"><button id="menu-toggle" type="button" class="btn" aria-expanded="false" aria-controls="collection-menu">Explore collections <span aria-hidden="true">▾</span></button><nav id="collection-menu" aria-label="Collections" class="panel p-3 absolute left-0 top-full mt-2 w-60 z-10 shadow-lg" hidden>'+''.join(f'<a class="block p-3 rounded-lg nav-link" href="#{id}">{text}</a>' for id,text in [('carry','Everyday carry'),('outdoors','Out on the trail'),('care','Care and repair')])+'</nav></div>'
        body=c.section('Choose your direction',f'<div class="panel p-7 min-h-0">{menu}{p("Equipment with a purpose, and a little guidance to help it last.","mt-5")}</div>')
        for i,(id,title) in enumerate([('carry','Everyday carry'),('outdoors','Out on the trail'),('care','Care and repair')]):body+=c.section(title,c.cards([(PRODUCTS[(n+i)%len(PRODUCTS)][0],PRODUCTS[(n+i)%len(PRODUCTS)][1],money(PRODUCTS[(n+i)%len(PRODUCTS)][2]),c.art('device' if i==0 else 'landscape',title,seed=i))]),id=id)
        c.scripts.append('''const trigger=document.getElementById('menu-toggle'),menu=document.getElementById('collection-menu');function closeMenu(){menu.hidden=true;trigger.setAttribute('aria-expanded','false');}trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));};document.addEventListener('click',event=>{if(!menu.contains(event.target)&&!trigger.contains(event.target))closeMenu();if(menu.contains(event.target)&&event.target.closest('a'))closeMenu();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!menu.hidden){closeMenu();trigger.focus();}});''')
    elif t==52:
        photos=pick([('ocean','Wind lines across the open water'),('forest','The forest before the first walkers arrive'),('mountain','Clouds resting on the mountain ridge'),('valley','A quiet valley in the late afternoon')],n,4)
        slides=''
        for i,(key,title) in enumerate(photos):slides+=f'<figure class="slide" {"hidden" if i else ""}>{c.image(key,title,"w-full h-64 md:h-96 object-cover")}<figcaption class="p-5"><h3 class="text-xl font-semibold">{e(title)}</h3>{p("Photographic field notes from a day spent looking a little longer.","mt-2")}</figcaption></figure>'
        body=c.section('Four frames from the field','<div class="panel overflow-hidden">'+slides+'<div class="flex flex-wrap gap-4 p-5 border-t divider justify-between items-center">'+btn('Previous',attrs='id=previous-slide',secondary=True)+'<span id="slide-position" role="status">1 / 4</span>'+btn('Next',attrs='id=next-slide')+'</div></div>')
        c.scripts.append('''const slides=[...document.querySelectorAll('.slide')];let current=0;function move(step){current=(current+step+slides.length)%slides.length;slides.forEach((slide,i)=>slide.hidden=i!==current);document.getElementById('slide-position').textContent=(current+1)+' / '+slides.length;}document.getElementById('previous-slide').onclick=()=>move(-1);document.getElementById('next-slide').onclick=()=>move(1);''')
    elif t==53:
        article=ARTICLES[n%len(ARTICLES)]
        body=c.section('Choose your reading light','<div class="panel p-6 flex flex-wrap gap-4 justify-between items-center"><p class="muted">A comfortable setting for the next few minutes.</p>'+btn('Use dark mode',attrs='id=theme-toggle aria-pressed=false')+'</div>')
        body+=c.section(article[0],f'<article class="panel p-7 md:p-10 max-w-3xl mx-auto">{tag(article[1])}<p class="text-lg leading-relaxed mt-6">{e(article[2])}</p>{p("Start by noticing one ordinary thing you usually pass. The corner shop opening its shutters. A tree holding the last of its leaves. Someone taking time to mend a worn handle instead of replacing it.","mt-5")}{p("Attention is a practice built from small choices. You do not need a perfect morning or an empty calendar to begin; a few unhurried minutes can be enough to see a familiar place differently.","mt-5")}<p class="text-sm accent mt-7">Words by {e(c.person)} · 4 minute read</p></article>')
        c.scripts.append('''document.getElementById('theme-toggle').onclick=function(){const dark=document.body.classList.toggle('dark-theme');this.setAttribute('aria-pressed',String(dark));this.textContent=dark?'Use light mode':'Use dark mode';};''')
    elif t==54:
        bill=round(28+n*3.25,2)
        fields=c.field('Bill amount · USD','number',name='bill',attrs=f'min="0" step="0.01" value="{bill}"')+c.field('Tip percentage','number',name='tip',attrs='min="0" max="100" step="1" value="18"')+c.field('People sharing','number',name='people',attrs='min="1" max="50" step="1" value="2"')
        body=c.section('The tip, made simple',f'<div class="grid gap-6 md:grid-cols-2"><form id="tip-form" class="panel p-6 space-y-5">{fields}<button type="submit" class="btn">Calculate</button></form><div class="panel p-7"><p class="eyebrow accent">At a glance</p><dl class="space-y-5 mt-6"><div><dt class="muted">Tip amount</dt><dd id="tip-value" class="text-2xl font-bold"></dd></div><div><dt class="muted">Total with tip</dt><dd id="total-value" class="text-2xl font-bold"></dd></div><div><dt class="muted">Each person pays</dt><dd id="person-value" class="text-4xl font-bold accent"></dd></div></dl><p id="tip-error" class="muted mt-5" role="status"></p></div></div>')
        c.scripts.append('''const form=document.getElementById('tip-form'),format=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'});function calculate(){const bill=Number(form.elements.bill.value),tip=Number(form.elements.tip.value),people=Number(form.elements.people.value);const valid=form.checkValidity()&&Number.isFinite(bill)&&Number.isFinite(tip)&&Number.isInteger(people);if(!valid){['tip-value','total-value','person-value'].forEach(id=>document.getElementById(id).textContent='—');document.getElementById('tip-error').textContent='Use a nonnegative bill, a 0–100% tip, and 1–50 whole people.';return;}const extra=Math.round(bill*tip)/100,total=bill+extra;document.getElementById('tip-error').textContent='';document.getElementById('tip-value').textContent=format.format(extra);document.getElementById('total-value').textContent=format.format(total);document.getElementById('person-value').textContent=format.format(total/people);}form.oninput=calculate;form.onsubmit=event=>{event.preventDefault();calculate();};calculate();''')
    elif t==55:
        deadline=f'2030-08-{10+n:02}T16:00:00Z'
        blocks=''.join(f'<div class="panel p-5 text-center"><span id="timer-{unit}" class="text-4xl md:text-5xl font-bold">00</span><span class="block text-sm muted mt-2">{unit.title()}</span></div>' for unit in ['days','hours','minutes','seconds'])
        body=c.section('The next chapter begins',f'<div class="panel p-7"><p class="text-lg mb-6">Launch date: <time datetime="{deadline}">August {10+n}, 2030 · 16:00 UTC</time></p><div id="countdown" class="grid grid-cols-2 md:grid-cols-4 gap-4" role="timer" aria-label="Time until launch" data-deadline="{deadline}">{blocks}</div><p id="countdown-status" role="status" class="muted mt-6">Getting ready for launch.</p></div>')+c.form('newsletter')
        c.scripts.append('''const deadline=Date.parse(document.getElementById('countdown').dataset.deadline);let clock;function tick(){let remaining=Math.max(0,Math.floor((deadline-Date.now())/1000));const values=[Math.floor(remaining/86400),Math.floor(remaining%86400/3600),Math.floor(remaining%3600/60),remaining%60];['days','hours','minutes','seconds'].forEach((unit,i)=>document.getElementById('timer-'+unit).textContent=String(values[i]).padStart(2,'0'));if(remaining===0){document.getElementById('countdown-status').textContent='The wait is over. Launch day is here.';clearInterval(clock);}}clock=setInterval(tick,1000);tick();''')
    elif t==56:
        craft=['Bookbinding','Natural dyeing','Small-batch ceramics','Field photography','Spoon carving'][n%5]
        dialog=f'<dialog id="workshop-dialog" class="panel p-7 modal-card"><h3 id="dialog-title" class="text-2xl font-bold">{craft}, from the beginning</h3>{p("A hands-on Saturday session, 10 AM–3 PM. Materials, shared tools, and a simple lunch are included.","mt-4")}<dl class="grid grid-cols-2 gap-4 my-6"><div><dt class="muted">Group size</dt><dd class="font-bold">8 participants</dd></div><div><dt class="muted">Workshop price</dt><dd class="font-bold">{money(65+n*3)}</dd></div></dl><form method="dialog"><button class="btn" autofocus>Close details</button></form></dialog>'
        body=c.section('A Saturday well spent',f'<div class="grid gap-6 md:grid-cols-2 items-center"><div class="panel overflow-hidden">{c.image("still6", "Hand tools and materials for an independent workshop", "w-full h-72 object-cover")}</div><div><h3 class="text-2xl font-semibold mb-4">{craft} for curious beginners</h3>{p("No previous experience is needed. Bring your questions and leave with something you made yourself.")}<div class="mt-6">{btn("View workshop details",attrs="id=open-dialog aria-haspopup=dialog")}</div></div></div>{dialog}')
        c.scripts.append('''const dialog=document.getElementById('workshop-dialog');dialog.setAttribute('aria-labelledby','dialog-title');document.getElementById('open-dialog').onclick=()=>dialog.showModal();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});''')
    elif t==57:
        body=c.section('An evening at the desk',f'<div class="panel p-8 text-center"><div id="bulb" class="light-bulb mx-auto w-32 h-32 rounded-full border-4 divider flex items-center justify-center text-2xl font-bold" aria-hidden="true">LED</div><p id="light-status" class="text-2xl font-semibold my-6" role="status">The light is off</p>{btn("Switch light on",attrs="id=light-toggle role=switch aria-checked=false")}<p class="muted text-sm mt-5">9 W LED · A warm light for reading and making.</p></div>')
        c.scripts.append('''document.getElementById('light-toggle').onclick=function(){const on=document.getElementById('bulb').classList.toggle('on');this.setAttribute('aria-checked',String(on));this.textContent=on?'Switch light off':'Switch light on';document.getElementById('light-status').textContent=on?'The light is on':'The light is off';};''')
    elif t==58:
        body=c.section('How quickly can you respond?',f'<div class="panel p-7 text-center"><button type="button" id="reaction-pad" class="reaction-pad" disabled>Press “Start round” when you are ready</button><p id="reaction-result" class="my-5 font-semibold" role="status">A steady focus beats a lucky guess.</p>{btn("Start round",attrs="id=start-reaction")}<p class="muted text-sm mt-5">Clicking before green ends the round. Your result measures this browser session.</p></div>')
        c.scripts.append('''let phase='idle',timeout,started=0;const pad=document.getElementById('reaction-pad'),start=document.getElementById('start-reaction'),result=document.getElementById('reaction-result');start.onclick=()=>{clearTimeout(timeout);phase='waiting';pad.disabled=false;pad.classList.remove('ready');pad.textContent='Wait for green…';result.textContent='Stay ready.';start.disabled=true;timeout=setTimeout(()=>{phase='ready';started=performance.now();pad.classList.add('ready');pad.textContent='Green! Click now';},900+Math.random()*1600);};pad.onclick=()=>{if(phase==='waiting'){clearTimeout(timeout);result.textContent='Too soon! Wait for the green signal next time.';}else if(phase==='ready'){result.textContent=Math.round(performance.now()-started)+' ms — your reaction time';}else return;phase='idle';pad.disabled=true;pad.classList.remove('ready');pad.textContent='Round finished';start.disabled=false;start.textContent='Try another round';};''')
    elif t==59:
        choices=[('rock',''),('paper',''),('scissors','')]
        buttons=''.join(btn(f'{symbol} {name.title()}',attrs=f'data-choice="{name}"',secondary=True) for name,symbol in choices)
        body=c.section('Make your move',f'<div class="panel p-7 text-center"><div class="flex flex-wrap gap-3 justify-center">{buttons}</div><p id="rps-result" class="text-xl font-semibold my-7" role="status">Choose a move to begin.</p><div class="grid grid-cols-3 gap-3 max-w-lg mx-auto">{metric("You","0") if False else ""}<div><p class="muted">You</p><output id="wins" class="text-3xl font-bold">0</output></div><div><p class="muted">Ties</p><output id="ties" class="text-3xl font-bold">0</output></div><div><p class="muted">Computer</p><output id="losses" class="text-3xl font-bold">0</output></div></div><div class="mt-7">{btn("Reset match",attrs="id=reset-match",secondary=True)}</div></div>')
        c.scripts.append('''const moves=['rock','paper','scissors'],beats={rock:'scissors',paper:'rock',scissors:'paper'},scores={wins:0,ties:0,losses:0};function display(){Object.keys(scores).forEach(key=>document.getElementById(key).textContent=scores[key]);}document.querySelectorAll('[data-choice]').forEach(button=>button.onclick=()=>{const player=button.dataset.choice,computer=moves[Math.floor(Math.random()*3)],outcome=player===computer?'ties':beats[player]===computer?'wins':'losses';scores[outcome]++;display();document.getElementById('rps-result').textContent='You chose '+player+'. Computer chose '+computer+'. '+({ties:'A tie.',wins:'You win this round!',losses:'Computer wins this round.'}[outcome]);});document.getElementById('reset-match').onclick=()=>{Object.keys(scores).forEach(key=>scores[key]=0);display();document.getElementById('rps-result').textContent='New match. Choose your move.';};''')
    elif t==60:
        symbols=pick(['LEAF','PEAR','ROSE','BEE','MOSS','LILY','FERN','CONE','BUD','SEED'],n,4)
        body=c.section('The memory garden',f'<div class="panel p-6 max-w-xl mx-auto"><div class="flex justify-between gap-4 mb-5"><p id="memory-status" role="status">0 / 4 pairs matched</p><p>Moves: <output id="memory-moves">0</output></p></div><div id="memory-grid" class="memory-grid"></div><div class="mt-6">{btn("Shuffle and restart",attrs="id=restart-memory",secondary=True)}</div></div>')
        c.scripts.append('''const symbols='''+json.dumps(symbols)+''',grid=document.getElementById('memory-grid');let first=null,locked=false,pairs=0,moves=0,pending;function startMemory(){clearTimeout(pending);first=null;locked=false;pairs=0;moves=0;grid.replaceChildren();document.getElementById('memory-moves').textContent='0';document.getElementById('memory-status').textContent='0 / 4 pairs matched';const deck=[...symbols,...symbols];for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}deck.forEach((symbol,i)=>{const card=document.createElement('button');card.type='button';card.className='memory-card';card.dataset.pair=symbol;card.textContent='?';card.setAttribute('aria-label','Reveal card '+(i+1));card.onclick=()=>{if(locked||card.disabled||card===first)return;card.textContent=symbol;card.setAttribute('aria-label','Card '+(i+1)+': '+symbol);if(!first){first=card;return;}moves++;document.getElementById('memory-moves').textContent=moves;if(first.dataset.pair===symbol){first.disabled=card.disabled=true;first.classList.add('matched');card.classList.add('matched');first=null;pairs++;document.getElementById('memory-status').textContent=pairs===4?'All four pairs found. Well remembered!':pairs+' / 4 pairs matched';}else{locked=true;const previous=first;pending=setTimeout(()=>{[previous,card].forEach(c=>{c.textContent='?';c.setAttribute('aria-label','Reveal a card');});first=null;locked=false;},700);}};grid.append(card);});}document.getElementById('restart-memory').onclick=startMemory;startMemory();''')
    elif t==61:
        maximum=50 if n%2 else 100
        body=c.section(f'Find the number from 1 to {maximum}',f'<div class="panel p-7 max-w-xl mx-auto"><form id="guess-form" class="space-y-5">{c.field("Your guess","number",name="guess",attrs=f"min=1 max={maximum} step=1")}<button class="btn" type="submit">Check guess</button></form><p id="guess-hint" class="my-5 font-semibold" role="status">Seven attempts. Make your first guess.</p><p class="muted text-sm">Previous guesses: <span id="guess-history">None yet</span></p><div class="mt-6">{btn("New number",attrs="id=new-number",secondary=True)}</div></div>')
        c.scripts.append(f'''const maximum={maximum},form=document.getElementById('guess-form'),input=form.elements.guess,hint=document.getElementById('guess-hint'),history=document.getElementById('guess-history');let target,guesses=[];function newNumber(){{target=1+Math.floor(Math.random()*maximum);guesses=[];input.disabled=false;form.querySelector('button').disabled=false;input.value='';history.textContent='None yet';hint.textContent='Seven attempts. Make your first guess.';}}form.onsubmit=event=>{{event.preventDefault();const value=Number(input.value);if(!Number.isInteger(value)||value<1||value>maximum)return;if(guesses.includes(value)){{hint.textContent='You already tried '+value+'. Choose another number.';return;}}guesses.push(value);history.textContent=guesses.join(', ');if(value===target)hint.textContent='Found it! The number was '+target+'. '+guesses.length+' attempts used.';else if(guesses.length===7)hint.textContent='Out of attempts. The number was '+target+'. Try a new number.';else hint.textContent=(value<target?'Too low.':'Too high.')+' '+(7-guesses.length)+' attempts remain.';if(value===target||guesses.length===7){{input.disabled=true;form.querySelector('button').disabled=true;}}else{{input.select();}}}};document.getElementById('new-number').onclick=newNumber;newNumber();''')
    if t not in [48,49,51,53,55]:
        tip=['Start with a small goal and make it your own.','Use the keyboard as well as the mouse; visible focus follows each control.','A fresh start is always available. Try another round at your own pace.'][n%3]
        body+=c.section('A moment, made useful',p(tip)+'<p class="text-sm muted mt-3">No sign-up, no leaderboard pressure. Just a clear little tool for right now.</p>')
    return body
